files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-inline-size: 360px;
  min-block-size: 100%;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 16px;
  background-color: #f2f2f2;
}

.content {
  grid-auto-rows: 650px;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: 650px 650px;
  gap: 2em;
  inline-size: 96%;
  max-inline-size: 80rem;
  padding: 40px 0;
}

.card {
  display: flex;
  flex-direction: column;
  border: 1px solid #000;
}

.card__image {
  inline-size: 100%;
  border-bottom: 1px solid #000;
  object-fit: cover;
  aspect-ratio: 4 / 3;
}

.card__title {
  margin-block-end: 0.3em;
  font-size: 1.6em;
  text-align: center;
  text-transform: uppercase;
}

.card__wrap {
  flex-grow: 1;
  padding: 0 10px;
}

.card__actions {
  display: flex;
  gap: 10px;
  padding: 0 10px 15px;
}

.card__link {
  display: flex;
  flex-grow: 1;
  justify-content: center;
  align-items: center;
  border: 1px solid #000;
  padding: 10px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-decoration: none;
  text-transform: uppercase;
}

.card__link.share {
  background-color: #ffc802;
}

.card__link.more {
  background-color: transparent;
}

.card__link:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.card__link:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

@media (width <= 950px) {
  body {
    font-size: 14px;
  }

  .content {
    gap: 0.8em;
  }
}
